def reference(models,capacity,blocks):
    current=None;res=set();refs={i:0 for i in models};epochs={};flows={};decisions=[];installs=[]
    used={'range':0,'exact':0}
    def usage(res):
        u={'range':0,'exact':0}
        for i in res:u[models[i]['spec']['mode']]+=models[i]['entries']
        return u
    def commit(fid,flow,at,reason,pat=None):
        model=models[flow['release']]
        if pat is None:
            prefix=flow['values'][:model['spec']['width']]
            prefix += [1514]*(model['spec']['width']-len(prefix))
            node=model['backup'][0]
            while len(node)>1:
                feature,threshold,left,right=node
                node=model['backup'][left if 2*prefix[feature]<=threshold else right]
            label=node[0];rule=start=None
        else:label=pat['class'];rule=pat['id'];start=len(flow['values'])-len(pat['range'])
        decisions.append(dict(flow=fid,epoch=flow['epoch'],release=flow['release'],at=at,seen=len(flow['values']),reason=reason,**{'class':label,'rule':rule,'start':start}))
        flow['done']=True
    for at,event in enumerate(e for b in blocks for e in b):
        op,fid=event[:2]
        if op=='install':
            model=models[fid];mode=model['spec']['mode'];entries=model['entries']
            if entries>capacity[mode]:status='oversize'
            else:
                nr=res|{fid}
                if current!=fid and current is not None and refs[current]==0:nr.remove(current)
                nu=usage(nr)
                if any(nu[m]>capacity[m] for m in capacity):status='busy'
                else:status='ok';res=nr;used=nu;current=fid
            installs.append(dict(at=at,id=fid,status=status,resident=sorted(res),used=used.copy()))
        elif op=='open':
            if current is None or fid in flows:raise ValueError()
            epoch=epochs.get(fid,-1)+1;epochs[fid]=epoch
            flows[fid]=dict(release=current,epoch=epoch,values=[],done=False,src=None,last=None)
            refs[current]+=1
        elif op=='close':
            if fid not in flows:raise ValueError()
            flow=flows.pop(fid);rid=flow['release']
            if not flow['done']:commit(fid,flow,at,'close')
            refs[rid]-=1
            if refs[rid]==0 and current!=rid:res.remove(rid);used=usage(res)
        else:
            if fid not in flows:raise ValueError()
            flow=flows[fid];ts,src,length=event[2:]
            if flow['last'] is not None and ts<flow['last']:raise ValueError()
            last=flow['last'];flow['last']=ts
            if flow['done']:continue
            spec=models[flow['release']]['spec'];n=len(flow['values'])
            if n>=spec['width'] and ts-last>spec['idle_us']:
                commit(fid,flow,at,'idle');continue
            if flow['src'] is None:flow['src']=src
            value=1514+length*(1 if src==flow['src'] else -1)
            flow['values'].append(value)
            for pat in models[flow['release']]['patterns']:
                L=len(pat['range'])
                if len(flow['values'])>=L and all(lo<=v<=hi for v,(lo,hi) in zip(flow['values'][-L:],pat['range'])):
                    commit(fid,flow,at,'segment',pat);break
            else:
                if len(flow['values'])>spec['packet_limit']:commit(fid,flow,at,'limit')
    if flows:raise ValueError()
    return installs,decisions,dict(current=current,resident=sorted(res),used=used)

